  /** Once daily. */
  QD = 'QD',
  /** Twice daily. */
  BID = 'BID',
  /** Three times daily. */
  TID = 'TID',
  /** Once daily at bedtime. */
  QHS = 'QHS',
  /** Once weekly. */
  QW = 'QW',
  /** As needed. */
  PRN = 'PRN',
